#include <bits/stdc++.h>
using namespace std;

// Conta subarrays (retangulos) com soma <= K usando janela deslizante.
// Valido pois todos os X_i >= 0 (extremo esquerdo monotono).
static long long countLE(const vector<int>& a, long long K) {
    if (K < 0) return 0; // impossivel ter soma negativa
    long long cnt = 0, s = 0;
    size_t l = 0;
    for (size_t r = 0; r < a.size(); r++) {
        s += a[r];
        while (s > K && l <= r) {
            s -= a[l];
            l++;
        }
        cnt += (long long)(r - l + 1);
    }
    return cnt;
}

int main() {
    int n;
    long long K;
    if (scanf("%d %lld", &n, &K) != 2) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    // Numero de subarrays com soma exatamente K:
    // (#subarrays com soma <= K) - (#subarrays com soma <= K-1)
    long long ans = countLE(a, K) - countLE(a, K - 1);
    printf("%lld\n", ans);
    return 0;
}
